\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Warm Parchment Color Theme ──
\definecolor{primary}{HTML}{3D2914}      % deep aged-ink brown
\definecolor{secondary}{HTML}{6B4423}    % warm brown
\definecolor{accent}{HTML}{C4501A}      % burnt orange
\definecolor{bgposter}{HTML}{F5EDE0}     % deep parchment
\definecolor{cardcream}{HTML}{FDF8F0}    % cream card
\definecolor{cardamber}{HTML}{FAF0E6}    % light amber
\definecolor{cardburnt}{HTML}{FDE8DC}     % burnt tint
\definecolor{textdark}{HTML}{1A1006}      % near-black
\definecolor{textgray}{HTML}{5C4A36}      % brown-gray
\definecolor{statbg}{HTML}{FCDABC}       % orange-tinted stat

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=4pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{22}{28}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Card styles (left accent stripe) ──
\tcbset{
  browncard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardcream,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=cardcream,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  orangecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardburnt,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=cardburnt,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.15},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardamber,
    borderline west={5pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=cardamber,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary,
    borderline west={6pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=5pt, bottomtitle=5pt,
    valign=top, drop shadow={opacity=0.22},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=35pt, right=35pt, top=10pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.35}
]{name=title, column=1, span=2, between=top and row4}{
  {\fontsize{72}{86}\selectfont\bfseries The History of Books}\\[10pt]
  {\fontsize{38}{46}\selectfont From Manuscripts to Mass Production}\\[8pt]
  {\fontsize{26}{32}\selectfont\color{white!80} 1,500 Years of Data on the Written Word}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=bgposter, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=4pt, bottom=4pt,
  valign=center, borderline={3pt}{0pt}{secondary!40},
]{name=stats, column=1, span=2, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{secondary!50}{statbg}{\parbox{0.9\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{56}{68}\selectfont\bfseries\color{primary} ~1440}\\[3pt]
      {\fontsize{22}{28}\selectfont\color{textdark} Gutenberg's Press Invented}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{secondary!50}{statbg}{\parbox{0.9\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{56}{68}\selectfont\bfseries\color{primary} 10}\\[3pt]
      {\fontsize{22}{28}\selectfont\color{textdark} Centuries of Manuscripts}\\[2pt]
      {\fontsize{18}{22}\selectfont\color{textgray} (6th–15th Century)}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{secondary!50}{statbg}{\parbox{0.9\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{56}{68}\selectfont\bfseries\color{primary} 500+}\\[3pt]
      {\fontsize{22}{28}\selectfont\color{textdark} Years of Book Data}\\[2pt]
      {\fontsize{18}{22}\selectfont\color{textgray} (1500–2009)}\vspace{5pt}%
    }}
  \end{minipage}
}

% ══ MAIN TIMELINE VISUAL ══
\posterbox[
  enhanced, colback=cardcream, boxrule=0pt, arc=0pt,
  left=16pt, right=16pt, top=6pt, bottom=6pt,
  borderline={2pt}{0pt}{secondary!30},
  halign=center, valign=center,
  drop shadow={opacity=0.12}
]{name=timeline, column=1, span=2, between=row6 and row13}{
  \fontsize{30}{36}\selectfont\bfseries\color{primary} Book Production: 600 CE – 2009\\[6pt]
  \fontsize{24}{30}\selectfont\color{textgray}
  {\begin{tabular}{p{0.45\linewidth}p{0.45\linewidth}}
    \rowcolors{1}{cardamber}{cardcream}
    \begin{tabular}{|c|p{60mm}|p{30mm}|}
      \hline
      \rowcolor{secondary!20}
      \textbf{Era} & \textbf{Description} & \textbf{Output Level} \\\hline
      600–1000 CE & Manuscript era, slow growth & Very Low \\\hline
      1000–1400 CE & Universities rise, literacy spreads & Low–Moderate \\\hline
      \rowcolor{accent!20}
      \textbf{~1440} & \textbf{\color{accent}Gutenberg Press} & \textbf{\color{accent}Inflection Point} \\\hline
      1500–1700 & Printed books replace manuscripts & High \\\hline
      1800–1900 & Industrial printing, mass production & Very High \\\hline
      1950–2009 & Global publishing industry & Exponential \\\hline
    \end{tabular}
    &
    \vspace{0pt}
    \includegraphics[width=0.92\linewidth,valign=c]{poster/figures/timeline_placeholder.png}\\[2pt]
    {\fontsize{18}{22}\selectfont\color{textgray}\textit{The contrast between the slow trickle of manuscripts and the explosive growth after Gutenberg is the story.}\\[4pt]
    \colorbox{accent!25}{\parbox{0.85\linewidth}{\centering\fontsize{20}{24}\selectfont\bfseries\color{accent}~20× increase in book output within 50 years of Gutenberg}}}
  \end{tabular}}
}

% ══ COLUMN 1: MANUSCRIPT ERA + GUTENBERG ══
\posterbox[browncard, title={The Manuscript Era (6th–15th Century)}
]{name=manuscripts, column=1, between=row13 and row16}{
  \fontsize{30}{40}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item Handwritten texts on scrolls \& codices
    \item Few thousand manuscripts produced per century
    \item Carolingian Renaissance (9th c.) boosted output
    \item 12th century: universities drove demand
  \end{itemize}
  \vspace{4pt}
  \colorbox{secondary!18}{\parbox{0.92\linewidth}{%
    \fontsize{26}{32}\selectfont\color{primary}\textbf{Peak}: ~100,000 manuscripts/year by the 15th century — all hand-copied
  }}
}

\posterbox[darkcard, title={The Gutenberg Revolution (~1440)}
]{name=gutenberg, column=1, between=row16 and row20}{
  \fontsize{30}{40}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item Movable type printing press invented
    \item Book output exploded across Europe
    \item Prices fell \textbf{75\%} within decades
  \end{itemize}
  \vspace{4pt}
  \colorbox{accent!20}{\parbox{0.92\linewidth}{%
    \fontsize{24}{30}\selectfont\color{accent}\textbf{First 50 years}: 30,000+ printed titles\\[4pt]
    \fontsize{22}{28}\selectfont\color{textgray} vs. the entire manuscript era's total output
  }}
  \vspace{6pt}
  \fontsize{26}{32}\selectfont\color{textgray}
  {\itshape "The printing press didn't just change publishing — it reshaped civilization."}
}

% ══ COLUMN 2: MODERN PUBLISHING + BOOKS AS MIRROR ══
\posterbox[orangecard, title={Modern Book Publishing}
]{name=modern, column=2, between=row13 and row16}{
  \fontsize{30}{40}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item Per-capita titles vary dramatically by country
    \item UNESCO: book = 49+ page published title
    \item Norway, Iceland lead; global average much lower
  \end{itemize}
  \vspace{4pt}
  \colorbox{accent!15}{\parbox{0.92\linewidth}{%
    \fontsize{24}{30}\selectfont\color{primary}\textbf{Data source}: Buringh \& Van Zanden (2009); Fink-Jensen (2015)
  }}
}

\posterbox[darkcard, title={Books as a Mirror of Society}
]{name=mirror, column=2, between=row16 and row20}{
  \fontsize{30}{40}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item \textbf{Literacy}: Higher output = greater literacy
    \item \textbf{Wealth}: Affordable books signal prosperity
    \item \textbf{Education}: School systems drive demand
    \item \textbf{Culture}: Religious texts $\rightarrow$ secular works
  \end{itemize}
  \vspace{6pt}
  \colorbox{primary!15}{\parbox{0.92\linewidth}{%
    \fontsize{24}{30}\selectfont\color{primary}\itshape From elite luxury to mass commodity — books shaped how humanity thinks.}
  }}
}

% ══ FOOTER / SOURCES ══
\posterbox[
  enhanced, colback=secondary!10, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=3pt, bottom=3pt,
  halign=center, valign=center,
  borderline={2pt}{0pt}{secondary!30}
]{name=footer, column=1, span=2, between=row20 and bottom}{
  \fontsize{22}{26}\selectfont\color{textgray}
  Sources: Buringh \& Van Zanden (2009), *Journal of Economic History* | Fink-Jensen (2015), IISH Data | Roser \& Ritchie (2023), *Our World in Data* (CC BY)
}

\end{tcbposter}
\end{document}

