223	  \end{itemize}
224	  \vspace{6pt}
225	  \colorbox{primary!15}{\parbox{0.92\linewidth}{%
226	    \fontsize{24}{30}\selectfont\color{primary}\itshape From elite luxury to mass commodity — books shaped how humanity thinks.}
227	  }}
