  \fontsize{24}{30}\selectfont\color{textgray}
  {\begin{tabular}{p{0.45\linewidth}p{0.45\linewidth}}
    \rowcolors{1}{cardamber}{cardcream}
    \begin{tabular}{|c|p{60mm}|p{30mm}|}
      \hline
      \rowcolor{secondary!20}
      \textbf{Era} & \textbf{Description} & \textbf{Output Level} \\\hline
      600–1000 CE & Manuscript era, slow growth & Very Low \\\hline
      1000–1400 CE & Universities rise, literacy spreads & Low–Moderate \\\hline
      \rowcolor{accent!20}
      \textbf{~1440} & \textbf{\color{accent}Gutenberg Press} & \textbf{\color{accent}Inflection Point} \\\hline
      1500–1700 & Printed books replace manuscripts & High \\\hline
      1800–1900 & Industrial printing, mass production & Very High \\\hline
      1950–2009 & Global publishing industry & Exponential \\\hline
    \end{tabular}
